async function scanBundle(input, deliver) {
    let delivered = 0;
    let lineNumber = 1;
    const lineParts = [];

    try {
        const decoder = new TextDecoder("utf-8");

        const processLine = async (raw, terminatedByLf) => {
            let line = raw;

            if (terminatedByLf && line.endsWith("\r")) {
                line = line.slice(0, -1);
            }

            if (/^[\t\r ]*$/.test(line)) {
                lineNumber++;
                return false;
            }

            let value;
            try {
                value = JSON.parse(line);
            } catch (_) {
                const error = new Error("Invalid JSON on line " + lineNumber);
                error.code = "BAD_LINE";
                error.line = lineNumber;
                throw error;
            }

            const result = await deliver(value, lineNumber);
            delivered++;

            if (result === false) {
                return true;
            }

            lineNumber++;
            return false;
        };

        const consume = async (text) => {
            let start = 0;

            while (true) {
                const end = text.indexOf("\n", start);

                if (end === -1) {
                    if (start < text.length) {
                        lineParts.push(text.slice(start));
                    }
                    return false;
                }

                if (end > start) {
                    lineParts.push(text.slice(start, end));
                }

                const line = lineParts.length === 0 ? "" : lineParts.join("");
                lineParts.length = 0;

                if (await processLine(line, true)) {
                    return true;
                }

                start = end + 1;
            }
        };

        while (true) {
            const chunk = await input.read();

            if (chunk === null) {
                break;
            }

            if (await consume(decoder.decode(chunk, { stream: true }))) {
                return delivered;
            }
        }

        if (await consume(decoder.decode())) {
            return delivered;
        }

        if (lineParts.length !== 0) {
            const line = lineParts.join("");
            lineParts.length = 0;

            if (await processLine(line, false)) {
                return delivered;
            }
        }

        return delivered;
    } finally {
        await input.close();
    }
}
